window.ScripturaLexicons.BDAG_PART_0264 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-01\" data-source=\"BDAG\" data-search=\"ὄψιος, α, ον adjetivo; substantivo feminino tardio; tarde; entardecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄψιος, α, ον</td><td>adjetivo; substantivo feminino</td><td>tardio; tarde; entardecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-02\" data-source=\"BDAG\" data-search=\"ὄψις, εως, ἡ substantivo feminino visão; aparência; rosto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄψις, εως, ἡ</td><td>substantivo feminino</td><td>visão; aparência; rosto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-03\" data-source=\"BDAG\" data-search=\"ὄψομαι forma verbal ver ὁράω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄψομαι</td><td>forma verbal</td><td>ver ὁράω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-04\" data-source=\"BDAG\" data-search=\"ὀψώνιον, ου, τό substantivo neutro soldo; salário; retribuição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀψώνιον, ου, τό</td><td>substantivo neutro</td><td>soldo; salário; retribuição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-05\" data-source=\"BDAG\" data-search=\"παγιδεύω verbo armar laço; apanhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παγιδεύω</td><td>verbo</td><td>armar laço; apanhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-06\" data-source=\"BDAG\" data-search=\"παγίς, ίδος, ἡ substantivo feminino armadilha; laço BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παγίς, ίδος, ἡ</td><td>substantivo feminino</td><td>armadilha; laço</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-07\" data-source=\"BDAG\" data-search=\"πάγκαρπος, ον adjetivo frutífero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάγκαρπος, ον</td><td>adjetivo</td><td>frutífero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-08\" data-source=\"BDAG\" data-search=\"πάγος substantivo; remissão ver Ἄρειος πάγος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάγος</td><td>substantivo; remissão</td><td>ver Ἄρειος πάγος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-09\" data-source=\"BDAG\" data-search=\"παθεῖν, παθών formas verbais ver πάσχω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παθεῖν, παθών</td><td>formas verbais</td><td>ver πάσχω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-10\" data-source=\"BDAG\" data-search=\"πάθημα, ατος, τό substantivo neutro sofrimento; sentimento; desejo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάθημα, ατος, τό</td><td>substantivo neutro</td><td>sofrimento; sentimento; desejo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-11\" data-source=\"BDAG\" data-search=\"παθητός adjetivo passível de sofrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παθητός</td><td>adjetivo</td><td>passível de sofrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-12\" data-source=\"BDAG\" data-search=\"πάθνη, ἡ substantivo feminino; remissão ver φάτνη BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάθνη, ἡ</td><td>substantivo feminino; remissão</td><td>ver φάτνη</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-13\" data-source=\"BDAG\" data-search=\"πάθνωμα substantivo neutro; remissão ver φάτνωμα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάθνωμα</td><td>substantivo neutro; remissão</td><td>ver φάτνωμα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-14\" data-source=\"BDAG\" data-search=\"πάθος, ους, τό substantivo neutro sofrimento; paixão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάθος, ους, τό</td><td>substantivo neutro</td><td>sofrimento; paixão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-15\" data-source=\"BDAG\" data-search=\"παιδαγωγός, οῦ, ὁ substantivo masculino guardião; condutor; guia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδαγωγός, οῦ, ὁ</td><td>substantivo masculino</td><td>guardião; condutor; guia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-16\" data-source=\"BDAG\" data-search=\"παιδάριον, ου, τό substantivo neutro criança; jovem escravo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδάριον, ου, τό</td><td>substantivo neutro</td><td>criança; jovem escravo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-17\" data-source=\"BDAG\" data-search=\"παιδεία, ας, ἡ substantivo feminino educação; disciplina; formação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδεία, ας, ἡ</td><td>substantivo feminino</td><td>educação; disciplina; formação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-18\" data-source=\"BDAG\" data-search=\"παιδευτής, οῦ, ὁ substantivo masculino instrutor; disciplinador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδευτής, οῦ, ὁ</td><td>substantivo masculino</td><td>instrutor; disciplinador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-19\" data-source=\"BDAG\" data-search=\"παιδεύω verbo educar; corrigir; disciplinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδεύω</td><td>verbo</td><td>educar; corrigir; disciplinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0264-20\" data-source=\"BDAG\" data-search=\"παιδιόθεν advérbio desde a infância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παιδιόθεν</td><td>advérbio</td><td>desde a infância</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0264-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄψιος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄψιος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀψέ</span>).<br>\n① Como adjetivo (Pind. [Isth. 4, 38f <span class=\"greek\">ὀψίᾳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">νυκτί</span> = tarde da noite] e outros; PTebt 304, 5 <span class=\"greek\">ὀψίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">γενομένης</span>; BGU 380, 3), relativo a um momento posterior a outro, tardio: <span class=\"greek\">ὀψίας</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">οὔσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span>, «Visto que a hora já estava avançada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:11</a> (ver <span class=\"greek\">ὀψέ</span> 2).<br>\n② Em nossa literatura, principalmente substantivado, <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀψία</span> (subentendido <span class=\"greek\">ὥρα</span>; B-D-F §241, 3), período entre o fim da tarde e o escurecer, entardecer, tarde, anoitecer (Ael. Aristid. 48, 50 K. = 24 p. 478 D.; POxy 475, 16 [182 d.C.] <span class=\"greek\">ὀψίας</span>, «à tarde»; 528, 5 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑκάστης</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀψίας</span>; PGM 1, 69; Jdth 13:1 <span class=\"greek\">ὡς</span> <span class=\"greek\">ὀψία</span> <span class=\"greek\">ἐγένετο</span>), geralmente na combinação <span class=\"greek\">ὀψίας</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γενομένης</span>, «Ao cair da tarde» (Syntipas p. 49, 11; TestSol 1:42; Jos., Ant. 5, 7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:16</a>; 14:15, 23; 20:8; 26:20; 27:57; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:32</a> (a expressão dupla <span class=\"greek\">ὀψ</span>. <span class=\"greek\">γενομένης</span>, <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἔδυσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλ</span>. é semelhante a Herm. Wr. 1, 29); Hs 9, 11, 6. <span class=\"greek\">ὀψίας</span> <span class=\"greek\">γενομένης</span>, «À tarde», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:35</a>; 6:47; 14:17. <span class=\"greek\">ἤδη</span> <span class=\"greek\">ὀψ</span>. <span class=\"greek\">γενομένης</span>, 15:42. Também <span class=\"greek\">οὔσης</span> <span class=\"greek\">ὀψίας</span> (Jos., Ant. 5, 140), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:19</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ὀψ</span>. <span class=\"greek\">ἐγένετο</span> (ver Jdth acima), 6:16. O contexto frequentemente permite determinar com mais facilidade a hora exata, antes ou depois do pôr do sol.—B. 997. DELG s.v. <span class=\"greek\">ὀψέ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄψις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (de <span class=\"greek\">ὀπωπα</span>, 2.º perfeito de <span class=\"greek\">ὀράω</span>; Hom. e posteriores).<br>\n① A experiência de ver algo, visão, ato de ver (Paus. 3, 14, 4 <span class=\"greek\">ὄψις</span> <span class=\"greek\">ὀνείρατος</span> = visão de um sonho; PFay 133, 11; Jos., Ant. 3, 38; Just., A I, 30, 1 e outros): <span class=\"greek\">ἡ</span> <span class=\"greek\">ὄψις</span> <span class=\"greek\">ὑμῶν</span>, «A visão de vós, vê-los», 1:3 (cf. Arrian, Anab. 6, 26, 3 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὄψει</span> <span class=\"greek\">πάντων</span>; Wsd 15:5 <span class=\"greek\">ὧν</span> <span class=\"greek\">ὄψις</span>).<br>\n② Aspecto externo ou físico de alguma coisa, aparência exterior, aspecto (Thu. 6, 46, 3; Timaeus Hist. [IV/III a.C.]: 566 Fgm. 13b Jac.; Diod S 4, 54, 5; Appian, Liby. 96 §454; Polyaenus 7, 6, 6; Gen 24:16; EpArist 77): <span class=\"greek\">τὴν</span> <span class=\"greek\">ὄψιν</span> <span class=\"greek\">νεωτέραν</span> <span class=\"greek\">ἔχειν</span>, «Parecer mais jovem», Hv 3, 10, 4; 3, 12, 1. <span class=\"greek\">ἀνήρ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἔνδοξος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὄψει</span>, «Um homem de aparência magnífica», 5:1 (TestAbr A 12 p. 90, 15 [Stone p. 28]; cf. SIG 1169, 30 <span class=\"greek\">ἔδοξε</span> <span class=\"greek\">τὰν</span> <span class=\"greek\">ὄψιν</span> <span class=\"greek\">εὐπρεπὴς</span> <span class=\"greek\">ἀνήρ</span>). Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:16</a> (ver 3 abaixo).—<span class=\"greek\">κατ</span>’ <span class=\"greek\">ὄψιν</span> <span class=\"greek\">κρίνειν</span>, «Julgar pela aparência exterior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24</a> (cf. Lysias, Orat. 16, 19 p. 147 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄξιον</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ὄψεως</span>, <span class=\"greek\">ὦ</span> <span class=\"greek\">βουλή</span>, <span class=\"greek\">οὔτε</span> <span class=\"greek\">φιλεῖν</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">μισεῖν</span> <span class=\"greek\">οὐδένα</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">σκοπεῖν</span>; POxy 37 II, 3; 1 Km 16:7; Jos., Bell. 3, 79).<br>\n③ Parte dianteira da cabeça ou sua expressão, rosto, semblante (Pla., Phdr. 254b; Phlegon: 257 Fgm. 36, 1, 3 Jac.; Diog. L. 6, 91f; PGiss 22, 5; PAmh 141, 12; BGU 451, 13; PGM 4, 746; 774; Jos., Ant. 6, 189; Iren 5, 30, 1 [Hv II 406, 3]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:44</a>; ApcPt 3:7a; <span class=\"greek\">τὸ</span> <span class=\"greek\">κάλλος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὄψ</span>., «A beleza do semblante», 3:7b. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:16</a> (ver 2 acima). Sobre o rosto de Deus (cf. POxy 1380, 127, referente a Ísis <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Λήθῃ</span> <span class=\"greek\">ἱλαρὰν</span> <span class=\"greek\">ὄψιν</span>; BGU 162, 4; 8 <span class=\"greek\">ὄψις</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Σοκνοπαίου</span>; 590, 19; Iren. 5, 31, 2 [Hv II 413, 2]), 1 Cl 36:2.—Também o plural <span class=\"greek\">αἱ</span> <span class=\"greek\">ὄψεις</span>, sobretudo «os olhos» (Pla., Theaet. 156b; Musonius p. 106, 8 H.; Vett. Val. 228, 6; 268, 1; 279, 30; POxy 911, 6; Tob 14:2 BA; Philo, Decal. 68, Ebr. 44; Orig., C. Cels. 7, 39, 47; <span class=\"greek\">ὄψεις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> 51, 29), provavelmente significa de modo mais geral «rosto» (Jos., Ant. 12, 81; TestReub 5:5; ApcMos 37 <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ὄψεσι</span> <span class=\"greek\">κείμενοι</span>): <span class=\"greek\">ἐνέπτυον</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ὄψεσι</span>, GPt 3:9.—DELG s.v. <span class=\"greek\">ὄπωπα</span> D. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄψομαι</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄψομαι</span>: ver <span class=\"greek\">ὁράω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀψώνιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀψώνιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (desde Menand., Fgm. 1051 J. = Fgm. 896 Kö.; emprego frequente a partir de Polyb., no singular e no plural; frequente em inscrições, papiros e óstracos; apenas três vezes na LXX, sempre no plural. Os aticistas o rejeitavam [Lob., Phryn. p. 420]), «dinheiro para provisões», ração (em dinheiro) paga a um soldado; daí:<br>\n① Pagamento, soldo, salário (acepção predominante; ver também SIG 410, 19, plural; LXX; EpArist 20:22 = Jos., Ant. 12:28, plural). O sentido mais geral de «provisões» talvez se ajuste a 1 Macc 14:32 (cf. SIG 700, 25) e a todas as ocorrências neotestamentárias (CCaragounis, NovT 16, ’74, 35–37).<br>\nⓐ Literalmente: <span class=\"greek\">ἀρκεῖσθε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀψωνίοις</span> <span class=\"greek\">ὑμῶν</span>, «Contentai-vos com vosso soldo» (dito por João Batista aos <span class=\"greek\">στρατευόμενοι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a>. <span class=\"greek\">στρατεύεσθαι</span> <span class=\"greek\">ἰδίοις</span> <span class=\"greek\">ὀψωνίοις</span>, «Servir como soldado às próprias custas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:7</a>.<br>\nⓑ Em linguagem figurada, os cristãos são soldados (sobre a vida cristã como serviço militar, ver <span class=\"greek\">πανοπλία</span> 2), cujo soldo é pago pelo general celestial: <span class=\"greek\">ἀρέσκετε</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">στρατεύεσθε</span>, <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀψώνια</span> <span class=\"greek\">κομίζεσθε</span>, IPol 6:2.—O ponto de vista militar parece passar para outro mais geral em <span class=\"greek\">λαβὼν</span> <span class=\"greek\">ὀψώνιον</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">διακονίαν</span>, «Recebendo sustento para poder servir-vos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:8</a> (sobre <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">ὀψώνιον</span>, cf. Polyb. 6, 39, 12; OGI 266, 7 [III a.C.]; PPetr II, 13 [17], 6 [258–253 a.C.]; PLond I, 23 [a], 26f, p. 38 [158–157 a.C.]; POxy 744, 7; cf. PWisc 68, 4 e outros, «ajuda de custo»).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:23</a> está ainda mais afastado do cenário militar e provavelmente deve ser classificado na acepção seguinte.<br>\n② Retribuição, recompensa ou compensação (IPriene 121, 34 [I a.C.], serviços públicos <span class=\"greek\">χωρὶς</span> <span class=\"greek\">ὀψωνίων</span>; 109, 94; 106 [II a.C.] <span class=\"greek\">ἄτερ</span> <span class=\"greek\">ὀψωνίου</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀψώνια</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">θάνατος</span>, «A retribuição paga pelo pecado (pelos serviços prestados a ele) é a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:23</a>.—DELG s.v. <span class=\"greek\">ὄψον</span>. M-M. TW. Spicq. <span class=\"greek\">Π</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παγιδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παγιδεύω</span> (<span class=\"greek\">παγίς</span>), subjuntivo do 1.º aoristo <span class=\"greek\">παγιδεύσω</span>; na LXX, termo da caça, Eccl 9:12: armar um laço ou uma armadilha, apanhar numa armadilha; figuradamente (1 Km 28:9; TestJos 7:1), <span class=\"greek\">ὅπως</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">παγιδεύσωσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">λόγῳ</span>, «Para que o apanhassem em alguma coisa que dissesse» (ver <span class=\"greek\">λόγος</span> 1a<span class=\"greek\">γ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:15</a> (cf. Atamanu, Graec. Venet. Pr 6:2 <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span>. Também na mesma versão, Dt 7:25; 12:30).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παγίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παγίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πήγνυμι</span>, cf. o verbete anterior; Aristoph. e outros; papiros, LXX; En 103:8), primariamente «armadilha, laço».<br>\n① Dispositivo empregado para capturar animais, armadilha, laço (Aristoph., Aves 527, Ranae 115; Anth. Pal. 6, 109; Pr 6:5; 7:23; Eccl 9:12): <span class=\"greek\">ὡς</span> <span class=\"greek\">π</span>., «Como uma armadilha», isto é, inesperadamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:35</a>. Como peça do equipamento de um passarinheiro (Aesop, Fab. 323 P. = 152 Babr; cf. 13 L-P.), Orig. e outros leem em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:29</a> no lugar de <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (Tdf., aparato).<br>\n② Aquilo que faz alguém correr perigo repentino ou ficar inesperadamente sob controle de uma força hostil, armadilha, laço, extensão figurada de 1 (Aristoph. e outros; LXX): <span class=\"greek\">γενηθήτω</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τράπεζα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">παγίδα</span>, «Que a mesa deles se transforme numa armadilha (para eles)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:9</a> (Ps 68:23). <span class=\"greek\">παγὶς</span> <span class=\"greek\">θανάτου</span>, «Laço mortal» (Tob 14:10a; Ps 17:6): sobre a duplicidade de fala, D 2:4; B 19:7 Funk; sobre a boca em geral, B 19:8 (cf. Pr 11:9; 18:7). <span class=\"greek\">ἐμπίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">παγίδα</span>, «Cair no laço» (Tob 14:10b; Pr 12:13; Sir 9:3): empregado absolutamente, <span class=\"greek\">εἰς</span> <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παγίδα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιθυμίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:9</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, 3:7. <span class=\"greek\">ἀνανήφω</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διαβόλου</span> <span class=\"greek\">παγίδος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:26</a>; ver <span class=\"greek\">ἀνανήφω</span>.—IScheftelowitz, Das Schlingen u. Netzmotiv 1912.—DELG s.v. <span class=\"greek\">πήγνυμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάγκαρπος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάγκαρπος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">καρπός</span>; Pind. e outros; Ps.-Pla., Axioch. 13, 371c; EpArist 63), que produz muitos frutos, fecundo: <span class=\"greek\">π</span>. <span class=\"greek\">ξύλον</span>, «Uma árvore carregada de frutos», figuradamente, Dg 12:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάγος</h1><div class=\"entry-meta\"><span>substantivo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάγος</span>: ver <span class=\"greek\">Ἄρειος</span> <span class=\"greek\">πάγος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παθεῖν, παθών</h1><div class=\"entry-meta\"><span>formas verbais</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παθεῖν</span>, <span class=\"greek\">παθών</span>: ver <span class=\"greek\">πάσχω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάθημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάθημα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πάσχω</span>; Soph., Hdt. e outros; Philo, Joseph.; Just., A II, 2, 16 [variante textual]; Ath. 28, 4).<br>\n① Aquilo que se sofre ou suporta, sofrimento, infortúnio; em nossa literatura, quase sempre no plural (Orig., C. Cels. 8, 599, 10. O plural também predomina nos autores não bíblicos: Plut., Mor. 360d; Appian, Bell. Civ. 2, 64 §269; 4, 1 §2; Jos., Ant. 2, 299): <span class=\"greek\">τὰ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">καιροῦ</span>, «Os sofrimentos que suportamos no tempo presente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:18</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6f</a> (sobre <span class=\"greek\">παθ</span>. … <span class=\"greek\">πάσχειν</span>, cf. Lamellae Aur. Orphicae, ed. AOlivieri 1915, p. 16, 4 [IV/III a.C.]). <span class=\"greek\">τὰ</span> <span class=\"greek\">παθήματα</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>, «Os sofrimentos (que eu, Paulo, estou suportando) por vós (colossenses)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:24</a> (JSchneider [ver abaixo], 54–61; JSchmid, BZ 21, ’33, 330–44; GKittel, ZST 18, ’41, 186–91; SHanson, The Unity of the Church, ’46, 119f). Com <span class=\"greek\">διωγμοί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:11</a>. <span class=\"greek\">ἄθλησις</span> <span class=\"greek\">παθημάτων</span>, «Uma luta acompanhada de sofrimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:32</a>. Sobre os sofrimentos dos cristãos perseguidos em geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:9</a>; ISm 5:1.—Sobre os sofrimentos de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a>. Esses sofrimentos estão continuamente diante dos olhos dos cristãos, 1 Cl 2:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">παθήματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, «Os sofrimentos de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:13</a>; 5:1 (<span class=\"greek\">θεοῦ</span> em P72). <span class=\"greek\">παθήματα</span> <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χρ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:10</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">παθήματα</span>, «Os sofrimentos de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:11</a> (ver <span class=\"greek\">εἰς</span> 4c<span class=\"greek\">β</span>; CScott, Exp. 6.ª série, 12, 1905, 234–40). Os cristãos que sofrem têm estreita relação com o Cristo sofredor. Sofrem como Cristo sofreu, ou por causa de Cristo, ou em união mística com Cristo. Cf. ASteubing, Der paul. Begriff ‘Christusleiden’, tese, Heidelberg 1905; TSchmidt, Der Leib Christi 1919, 210ff; RPaulus, Das Christusproblem der Gegenwart 1922, 24f; RLiechtenhan, ZTK 32, 1922, 368–99; OSchmitz, Das Lebensgefühl d. Pls, 1922, 50ff, 105ff; J Schneider, D. Passionsmystik des Pls 1929; ASchweitzer, D. Mystik des Ap. Pls 1930, 141–58 (The Mysticism of Paul the Ap., tradução de WMontgomery ’31, 141–59); BAhern, CBQ 22, ’60, 1–32 e outros.—O singular (Arrian, Anab. 4, 22, 2 = sofrimento, infortúnio; 6, 11, 2; 3 sobre o ferimento de Alexandre) ocorre apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:9</a>, referente a Cristo: <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> (genitivo epexegético), «Por causa da morte que sofreu».<br>\n② Experiência interior de natureza afetiva, sentimento, interesse (como <span class=\"greek\">πάθος</span>, porém menos frequente do que este. Pla., Phd. 79d [sobre o estado da alma quando empenhada na investigação mais pura] e outros; Aristot. [HBonitz, Index Aristot. 1870, 554]; Plut., Pomp. 622 [8, 6]), em sentido negativo (Plut., Mor. 1128e); em nossa literatura, somente em Paulo e somente no plural: interesses, desejos; <span class=\"greek\">τὰ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span>, «Os desejos pecaminosos» (não restritos ao interesse sexual), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:5</a>. Com <span class=\"greek\">ἐπιθυμίαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:24</a>.—B. 1089f. DELG s.v. <span class=\"greek\">πάσχω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παθητός</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παθητός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πάσχω</span>, cf. <span class=\"greek\">πάθημα</span>; Aristot. e posteriores), adjetivo verbal de <span class=\"greek\">πάσχω</span> (B-D-F §65, 3; Rob. 1097), sujeito ao sofrimento, passível de sofrer (Plut., Mor. 765b; 1026d, Pelop. 286 [16, 5], Numa 65 [8, 7], frequentemente em oposição a <span class=\"greek\">ἀπαθής</span>; Herm. Wr. 6, 2ab; 10, 17; Sallust. 4 p. 8, 7; Philo, Spec. Leg. 3, 180; Ath. 16, 3; R. 10 p. 59, 3), a respeito do Messias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:23</a>. Em oposição a <span class=\"greek\">ἀπαθής</span> (ver Proclus, Theol. 80 p. 74, 32), IEph 7:2; IPol 3:2.—DELG s.v. <span class=\"greek\">πάσχω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάθνη, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάθνη</span>, <span class=\"greek\">ἡ</span>: ver <span class=\"greek\">φάτνη</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάθνωμα</h1><div class=\"entry-meta\"><span>substantivo neutro; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάθνωμα</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span>: ver <span class=\"greek\">φάτνωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάθος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάθος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πάσχω</span>; trágicos, Hdt. e posteriores).<br>\n① Aquilo que é suportado ou experimentado, sofrimento (trágicos, Hdt. e outros; Diod S 1, 97, 4 <span class=\"greek\">τὰ</span> <span class=\"greek\">πάθη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> [diversas experiências dolorosas dos deuses: a luta contra os Titãs etc.]; Jos., Ant. 15, 57; 16, 315; Just., A I, 22, 4; Ath. 30, 4); assim, em nossa literatura, apenas em B 6:7 e em Inácio (mas frequentemente nos escritos deste), sempre no singular e em referência aos sofrimentos físicos de Cristo (também B 6:7; cf. Just., D. 97, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σταυρόν</span>; Iren. 3, 18, 3 [Harv. II 97, 3]; Orig., C. Cels. 1, 54, 2). IEph 20:1; IMg 5:2; ITr ins; 11:2; IPhld 9:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">θεομακάριστον</span> <span class=\"greek\">π</span>., «O sofrimento bendito por Deus», ISm 1:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μου</span>, «O sofrimento do meu Deus», IRo 6:3. Por seu próprio batismo e seu sofrimento, Cristo consagrou a água do batismo para os cristãos, IEph 18:2. <span class=\"greek\">ἀγαλλιᾶσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «Alegrar-se na Paixão do Senhor», IPhld ins. <span class=\"greek\">μετανοεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>., «Mudar de opinião acerca do sofrimento», ISm 5:3. Sobre a igreja: <span class=\"greek\">ἐκλελεγμένη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάθει</span> <span class=\"greek\">ἀληθινῷ</span>, «Escolhida na Paixão verdadeira», IEph ins. Empregado ao lado de <span class=\"greek\">ἀνάστασις</span>, de modo que equivale a <span class=\"greek\">θάνατος</span> (Appian, Bell. Civ. 1, 28 §129, morte de Nônio; 1, 38 §169, de Druso; 5, 59 §250. Ver <span class=\"greek\">πάσχω</span> 3a<span class=\"greek\">α</span>), IMg 11; ISm 7:2; 12:2. <span class=\"greek\">τῷ</span> <span class=\"greek\">π</span>. <span class=\"greek\">συγκατατίθεσθαι</span>, «Concordar com a Paixão (de Cristo), participar dela», IPhld 3:3.<br>\n② Experiência de desejo intenso, paixão (Pla. e outros; frequente em 4 Macc; Philo; Jos., C. Ap. 1, 214; Ar. 8, 2; Just., A I, 53, 12; Tat. 19, 3; Ath.; <span class=\"greek\">οὐ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀργή</span>, Orig., C. Cels. 4, 72, 1), especialmente de natureza sexual (Pla.; PMich 149 VI, 30 [II d.C.] <span class=\"greek\">π</span>. <span class=\"greek\">αἰσχρόν</span>; Ps.-Phoc. 194; Jos., Ant. 2, 53; Did., Gen. 138, 1): <span class=\"greek\">ἐν</span> <span class=\"greek\">πάθει</span> <span class=\"greek\">ἐπιθυμίας</span>, «Em paixão lasciva», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:5</a> (Ath. 21, 1 <span class=\"greek\">πάθη</span> <span class=\"greek\">ὀργῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιθυμίας</span>). Em uso absoluto (junto de outros vícios, alguns também de caráter sexual), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:5</a>. Acerca de uma mulher adúltera: <span class=\"greek\">ἐπιμένειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τούτῳ</span>, «Persistir nessa paixão», Hm 4, 1, 6. No plural: <span class=\"greek\">πάθη</span> <span class=\"greek\">ἀτιμίας</span>, «Paixões vergonhosas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:26</a>.—Também sobre a paixão da ira, Hs 6, 5, 5, variante textual (cf. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φιλαργυρίας</span> <span class=\"greek\">π</span>., Did., Gen. 126, 15).—RRabel, Diseases of the Soul in Stoic Psychology: Greek, Roman, and Byzantine Studies 22, ’81, 385–93. Ver a discussão ao fim de <span class=\"greek\">πάσχω</span>.—B. 1089f. DELG s.v. <span class=\"greek\">πάσχω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδαγωγός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδαγωγός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παῖς</span>, <span class=\"greek\">ἄγω</span>), desde Eur.; Hdt. 8, 75; Plut.; inscrições [referências em SIG 1253, nota 1]; papiros, Philo; Jos., Ant. 1, 56; 18, 202, Vi. 429. Comum como empréstimo no hebraico rabínico [SKrauss, Griech. u. lat. Lehnwörter im Talmud usw. II 1899, 421]). Originalmente «aquele que conduz o menino»: homem, geralmente escravo (Plut., Mor. 4ab), incumbido de levar um menino ou jovem (Plut., Mor. 439f) à escola e trazê-lo de volta e de supervisionar sua conduta em geral; não era um «professor» (apesar do significado atual do derivado «pedagogo» [ver OED s.v. 1a em contraste com 2]; <span class=\"greek\">παιδαγωγός</span> e <span class=\"greek\">διδάσκαλος</span> são distinguidos em X., De Rep. Lac. 3, 2; Pla., Lys. 208c [JCallaway, JBL 67, ’48, 353–55]; Diog. L. 3, 92; Philo, Leg. ad Gai. 53). Quando o jovem atingia a maioridade, o <span class=\"greek\">π</span>. deixava de ser necessário (cf. a reclamação de Gaio sobre as intenções de Macro em Philo, In Facc. 3 (15); ver JMarquardt2-AMau, D. Privatleben der Römer 1886, 114; WBecker-HGöll, Charikles II3 1878, 46ff [tradução inglesa de FMetcalfe, 1889, 226f]; ABaumeister, Denkmäler d. klass. Altertums 1885–88 II, 1125f). Em nossa literatura, aquele que tem responsabilidade por alguém que necessita de orientação, guardião, condutor, guia. Como pessoa à qual se deve respeito, ao lado do pai (como em Plut., Lyc. 50 [17, 1]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:15</a>. A lei como <span class=\"greek\">π</span>. (assim Plut., Mor. 645bc <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">καθάπερ</span> <span class=\"greek\">παιδαγωγοῦ</span>). Paulo considera a lei mosaica como <span class=\"greek\">παιδ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">Χριστόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:24</a>, enfatizando a função restritiva da lei, em contraste com a liberdade no evangelho. A humanidade permanece sob suas restrições, <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">παιδαγωγόν</span>, v. 25, até que Deus declare, mediante o envio de seu Filho, que ela atingiu a maioridade (ver <span class=\"greek\">υἱοθεσία</span>).—DLull, JBL 105, ’86, 481–98, sobre as limitações temporais da lei; TGordon, NTS 35, ’89, 150–54, papel do guardião; NYoung, Paidagogos, The Social Setting of a Pauline Metaphor: NovT 29, ’87, 150–76.—Pauly-W. 18/2, 2375–85; Kl. Pauly IV 408. Straub 61. DELG s.v. <span class=\"greek\">ἄγω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">παῖς</span>; com variados sentidos em Aristoph., Pla. e outros; inscrições, papiros, LXX, TestSol; TestAbr B 2 p. 107, 2 [Stone p. 62]; JosAs; Jos., Ant. 17, 13), diminutivo de <span class=\"greek\">παῖς</span>.<br>\n① Criança (também do sexo feminino: Aristoph., Th. 1203; Hyperid., Fgm. 164; Menand., Fgm. 361 Kö.).<br>\nⓐ Crianças brincando, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a>, variante textual.<br>\nⓑ Jovem que já não é criança (Gen 37:30 e cf. v. 2, em que se diz que José tinha dezessete anos; Tob 6:3; JosAs 27:2, referente a Benjamim, com dezenove anos); assim talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>. Mas esta passagem também pode pertencer à acepção<br>\n② Jovem escravo (Callixenus [III a.C.]: 627 Fgm. 2 p. 173, 14, 17 Jac.; X., Ag. 1, 21; Diog. L. 6, 52. Frequente nos papiros; 1 Km 25:5; Ruth 2:5, 9), MPol 6:1; 7:1. GSimpson, Semantic Study of Words for Young Person, Servant and Child in the Septuagint and Other Early Koine Greek, tese, Sydney ’76.—New Docs 1, 87. Schmidt, Syn. II 429f. DELG s.v. <span class=\"greek\">παῖς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παιδεύω</span>; «formação cultural», Aeschyl., Thu. e posteriores).<br>\n① A ação de proporcionar orientação para uma vida responsável, educação, formação, instrução; em nossa literatura, sobretudo enquanto obtida por meio de disciplina, correção (LXX, PsSol; TestZeb 2:3), referente à disciplina santa de um Deus paternal, 1 Cl 56:16. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">παιδεία</span>, «Toda disciplina», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:11</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παιδείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «Os oráculos do ensinamento de Deus», 1 Cl 62:3. <span class=\"greek\">ἐκτρέφειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">νουθεσίᾳ</span> <span class=\"greek\">κυρίου</span>, «Criar alguém na disciplina e instrução do Senhor» (= disciplina e instrução cristãs), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:4</a>. <span class=\"greek\">μισεῖν</span> <span class=\"greek\">παιδείαν</span>, «Odiar a disciplina», 1 Cl 35:8 (Ps 49:17; cf. Pr 5:12). <span class=\"greek\">ὀλιγωρεῖν</span> <span class=\"greek\">παιδείας</span> <span class=\"greek\">κυρίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:5</a> (Pr 3:11). <span class=\"greek\">ἀναλαμβάνειν</span> <span class=\"greek\">παιδείαν</span>, «Aceitar correção» (cf. <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">παιδείαν</span>, Pr 8:10; Jer 39:33; 42:13), 1 Cl 56:2. <span class=\"greek\">παιδεύειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">παιδείαν</span> (X., Cyr. 8, 3, 37; Aeschin., Or. 3, 148; Ps.-Demosth. 35, 42; ver também <span class=\"greek\">παιδεύω</span> 2a): <span class=\"greek\">παιδεύειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φόβου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «Educar alguém por meio de formação que conduz ao temor de Deus», 21:6 = Pol 4:2. <span class=\"greek\">παιδεύειν</span> <span class=\"greek\">παιδείᾳ</span> (Pla., Leg. 5 p. 741a; X., Cyr. 1, 1, 6): <span class=\"greek\">παιδεύεσθαι</span> <span class=\"greek\">παιδείᾳ</span> <span class=\"greek\">δικαίᾳ</span>, «Ser corrigido com disciplina justa», Hv 2, 3, 1. <span class=\"greek\">παραδίδοσθαί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">π</span>., «Ser entregue a alguém para boa instrução», Hs 6, 3, 6. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">παιδείας</span> <span class=\"greek\">μεταλαμβάνειν</span>, «Participar de uma educação cristã», 1 Cl 21:8. <span class=\"greek\">ὠφέλιμος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">παιδείαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span>, «Útil para instrução na justiça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:16</a>. Sobre a disciplina aplicada por Deus (PsSol 7:9 e outros; Cyrill. Scyth. p. 38, 8; 23): <span class=\"greek\">χωρὶς</span> <span class=\"greek\">παιδείας</span> <span class=\"greek\">εἶναι</span>, «Estar sem disciplina (divina)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:8</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">παιδείαν</span> <span class=\"greek\">ὑπομένετε</span>, «Deveis suportar (vossas provações) como disciplina (divina)», v. 7 (GBornkamm, Sohnschaft u. Leiden, ’60, 188–98). <span class=\"greek\">π</span>. <span class=\"greek\">εἰρήνης</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span>, «O castigo que nos trouxe paz caiu sobre ele», 1 Cl 16:5 (Is 53:5).<br>\n② Estado de quem recebeu educação adequada, formação (Diod S 12, 13, 4; 12, 20, 1; OGI 504, 8 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">παιδείᾳ</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἄλλῃ</span> <span class=\"greek\">ἀρετῇ</span>; Sir 1:27; Jos., Vi. 196; 359, C. Ap. 1, 73; Just., A I 1, 1 e outros; Tat. 12, 5 <span class=\"greek\">ἡμετέρας</span> <span class=\"greek\">παιδείας</span> e outros; Ath.): <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">παιδείαν</span>, «Não ter formação», Hv 3, 9, 10. A palavra pode ter essa acepção em algumas das passagens tratadas em 1.—WJaeger, Paideia I–III ’34–47 (tradução inglesa por GHighet, ’39–44); HvArnim, Leb. u. Werke des Dio v. Prusa mit e. Einleitung: Sophistik, Rhetorik, Philosophie in ihrem Kampf um d. Jugendbildung 1898; GBertram, Der Begriff d. Erziehung in d. griech. Bibel: Imago Dei (GKrüger Festschr.) ’32, 33–52; WJentzsch, Urchristl. Erziehungsdenken ’51. MHengel, Judaism ’74, sobretudo I 65–78.—DELG s.v. <span class=\"greek\">παῖς</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδευτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδευτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παιδεύω</span>; Pla. e outros; inscrições; Sb 5941, 2; LXX; PsSol 8:29; Tat. 22, 1), instrutor, mestre (Pla., Leg. 7, 811d; Plut., Lyc. 46 [12, 4], Camill. 134 [10, 3], Mor. 4c; Diog. L. 7, 7; inscrições; Sir 37:19; 4 Macc 5:34; Philo, Omn. Prob. Lib. 143): <span class=\"greek\">π</span>. <span class=\"greek\">ἀφρόνων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:20</a>.—Por vezes, a ênfase recai sobre a ideia de corrigir ou disciplinar: corretor, aquele que disciplina (ver <span class=\"greek\">παιδεύω</span> 2 e cf. Hos 5:2; PsSol 8, 29), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδεύω</span> (ver o verbete anterior), imperfeito <span class=\"greek\">ἐπαίδευον</span>; futuro <span class=\"greek\">παιδεύσω</span> na LXX; 1.º aoristo <span class=\"greek\">ἐπαίδευσα</span>. Passivo: 1.º futuro <span class=\"greek\">παιδευθήσομαι</span> na LXX; 1.º aoristo <span class=\"greek\">ἐπαιδεύθην</span>; particípio perfeito <span class=\"greek\">πεπαιδευμένος</span>.<br>\n① Proporcionar instrução para uma vida informada e responsável, educar (trágicos e posteriores; Pla.; X.; inscrições, papiros; TestSol 1:13 D [<span class=\"greek\">ἐπαιδεύθη</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σοφίαν</span>]; EpArist, Philo; Jos., C. Ap. 1, 22 <span class=\"greek\">γράμμασιν</span> <span class=\"greek\">ἐπαιδεύθησαν</span>; Tat. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">παιδεύει</span> <span class=\"greek\">λέγων</span>; Did., Gen. 102, 18): <span class=\"greek\">ἐπαιδεύθη</span> <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">σοφίᾳ</span> <span class=\"greek\">Αἰγυπτίων</span>, «Moisés foi educado em toda a cultura dos egípcios», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:22</a>. <span class=\"greek\">πεπαιδευμένος</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ἀκρίβειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρῴου</span> <span class=\"greek\">νόμου</span>, «Educado rigorosamente segundo a lei de nossos pais», 22:3 (cf. Jos., Bell. 7, 343). CBurchard, ZNW 61, ’70, 168f, prefere uma vírgula depois de <span class=\"greek\">πεπαιδ</span>.<br>\n② Ajudar no desenvolvimento da capacidade de uma pessoa para fazer escolhas adequadas, exercitar a disciplina.<br>\nⓐ Corrigir, orientar (LXX), <span class=\"greek\">τινά</span>, alguém (TestZeb 2:3; Aelian, VH 1, 34): <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀντιδιατιθεμένους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:25</a>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐκλεκτούς</span>, <span class=\"greek\">ἀλλήλους</span>, Hv 3, 9, 10. <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐπαίδευσας</span>, «Por meio de quem (isto é, Cristo) tu (isto é, Deus) nos conduziste pelo caminho correto», 1 Cl 59:3, em jogo de palavras com o precedente <span class=\"greek\">παῖς</span>. <span class=\"greek\">παιδευθῆναι</span> <span class=\"greek\">παιδείᾳ</span> <span class=\"greek\">δικαίᾳ</span>, Hv 2, 3, 1. <span class=\"greek\">παιδεύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παιδείαν</span> (Ammonius, Vi. Aristot. p. 10, 20 Westerm; ver também <span class=\"greek\">παιδεία</span> 1), 1 Cl 21:6 = Pol 4:2. Seguido de <span class=\"greek\">ἵνα</span>, «Conduzir a», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:12</a>.<br>\nⓑ Disciplinar mediante castigo.<br>\n<span class=\"greek\">α</span>. Sobretudo sobre a disciplina divina (Cyrill. Scyth. p. 37, 23; 73, 3 <span class=\"greek\">παιδευόμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαίμονος</span>; LXX; ApcSed 3:7 [cf. 4:1]; ApcrEzk P 1 recto, 6; Theoph. Ant. 2, 26 [p. 162, 17]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:6</a>; 1 Cl 56:4 (ambos Pr 3:12). Com <span class=\"greek\">ἐλέγχειν</span> (Ps 6:2; 37:2), 1 Cl 56:5 (Ps 140:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:19</a> (cf. Pr 3:12 com variante textual). <span class=\"greek\">παιδεύων</span> <span class=\"greek\">ἐπαίδευσέν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>, 1 Cl 56:3 (Ps 117:18). Cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:10b</a>.—Na voz passiva (PsSol 3:4; 13:8; Laud. Therap. 19 <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">παιδεύεται</span> = «O corpo é disciplinado [por Deus]»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:9</a>; 1 Cl 56:16. <span class=\"greek\">παιδευθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μετάνοιαν</span>, «Aceitar correção para arrepender-se», 57:1. Uma disciplina salutar pode ser exercida até por meio de Satanás; passiva seguida de infinitivo (B-D-F §392, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:20</a>.<br>\n<span class=\"greek\">β</span>. Disciplina aplicada por pais humanos (Pr 19:18; 28:17a; 29:17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:7</a>, 10a.<br>\n<span class=\"greek\">γ</span>. Disciplinar por açoites ou flagelação (Vi. Aesopi G 61 P.; 3 Km 12:11, 14; 2 Ch 10:11, 14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:16</a>, 22 (em contraste com <span class=\"greek\">φραγγελόω</span>, ASherwin-White, Rom. Society and Rom. Law in the NT, ’63, 27f).—B. 1446f. DELG s.v. <span class=\"greek\">παῖς</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0264-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παιδιόθεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παιδιόθεν</span>, advérbio, desde a infância: <span class=\"greek\">ἐκ</span> <span class=\"greek\">π</span>. (Gen 47:3 A; MartPtPl 39 [Aa I 152, 12].—B-D-F §104, 3; Rdm.2 32; Mlt-H. 164), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:21</a>.—MLejeune, Les adverbes grecs en-<span class=\"greek\">θεν</span> ’39. Ver <span class=\"greek\">παιδόθεν</span>.—DELG s.v. <span class=\"greek\">παῖς</span>. M-M.</p></section></article>"};
